	private static void assertRejectedDatatype(Literal.BaseDirection direction) {
		Literal term = VF.createLiteral("value", "en", direction);
		var bag = SolutionBagCodec.fromBindingSets(List.of("value"), List.of(row("value", term)));
		String encoded = SolutionBagCodec.encode(bag);
		assertEquals(bag, SolutionBagCodec.decode(encoded));
		String originalDatatype = "\"datatype\":\"" + term.getDatatype().stringValue() + "\"";
		for (var incompatible : List.of(XSD.STRING, RDF.LANGSTRING, RDF.DIRLANGSTRING)) {
			if (incompatible.equals(term.getDatatype())) {
				continue;
			}
			String corrupted = encoded.replace(originalDatatype,
					"\"datatype\":\"" + incompatible.stringValue() + "\"");
			assertNotEquals(encoded, corrupted, "the fixture changes the stored literal datatype");
			assertThrows(IllegalArgumentException.class, () -> SolutionBagCodec.decode(corrupted), direction.name());
		}
		String missingDatatype = encoded.replace(originalDatatype + ",", "");
		assertNotEquals(encoded, missingDatatype, "the fixture removes the stored literal datatype");
		assertThrows(IllegalArgumentException.class, () -> SolutionBagCodec.decode(missingDatatype), direction.name());
	}

