	private static SolutionBagCodec.Row nestedRow(String first, String second) {
		var outerNode = VF.createBNode(first);
		var innerNode = VF.createBNode(second);
		Value nested = Values.tripleTerm(outerNode, Values.iri("urn:codec:outer"),
				Values.tripleTerm(innerNode, Values.iri("urn:codec:inner"), outerNode));
		return new SolutionBagCodec.Row(List.of(outerNode, nested));
	}

	@Test
	void agreesWithExhaustiveSmallBlankNodeBijections() {
		Random random = new Random(0x45ab719L);
		int nodeCount = 3;
		for (int sample = 0; sample < 120; sample++) {
			int edgeCount = random.nextInt(8);
			List<int[]> left = randomEdges(random, edgeCount, nodeCount);
			List<int[]> right;
			if ((sample & 1) == 0) {
				List<Integer> order = new ArrayList<>(List.of(0, 1, 2));
				Collections.shuffle(order, random);
				right = left.stream().map(edge -> new int[] { order.get(edge[0]), order.get(edge[1]) }).toList();
			} else {
				right = randomEdges(random, edgeCount, nodeCount);
			}
			boolean expected = exhaustiveBijection(left, right, new int[nodeCount], new boolean[nodeCount], 0);
			var leftBag = graphBag("left-", left);
			var rightBag = graphBag("right-", right);
			assertEquals(expected, SolutionBagCodec.isomorphic(leftBag, rightBag), "sample " + sample);
			assertEquals(expected, SolutionBagCodec.isomorphic(rightBag, leftBag), "reversed sample " + sample);
		}
	}

	private static List<int[]> randomEdges(Random random, int count, int nodeCount) {
		List<int[]> edges = new ArrayList<>();
		for (int index = 0; index < count; index++) {
			edges.add(new int[] { random.nextInt(nodeCount), random.nextInt(nodeCount) });
		}
		return edges;
	}

	private static SolutionBagCodec.Bag graphBag(String prefix, List<int[]> edges) {
		List<SolutionBagCodec.Row> rows = new ArrayList<>();
		for (int[] edge : edges) {
			rows.add(new SolutionBagCodec.Row(List.of(VF.createBNode(prefix + edge[0]),
					VF.createBNode(prefix + edge[1]))));
		}
		return SolutionBagCodec.fromRows(List.of("from", "to"), rows);
	}

	private static boolean exhaustiveBijection(List<int[]> left, List<int[]> right, int[] mapping, boolean[] used,
			int position) {
		if (position == mapping.length) {
			Map<String, Integer> mappedCounts = new HashMap<>();
			Map<String, Integer> rightCounts = new HashMap<>();
			for (int[] edge : left) {
				mappedCounts.merge(mapping[edge[0]] + ":" + mapping[edge[1]], 1, Integer::sum);
			}
			for (int[] edge : right) {
				rightCounts.merge(edge[0] + ":" + edge[1], 1, Integer::sum);
			}
			return mappedCounts.equals(rightCounts);
		}
		for (int candidate = 0; candidate < mapping.length; candidate++) {
			if (!used[candidate]) {
				mapping[position] = candidate;
				used[candidate] = true;
				if (exhaustiveBijection(left, right, mapping, used, position + 1)) {
					return true;
				}
				used[candidate] = false;
			}
		}
		return false;
	}

