	@Test
	void comparesLargeBagsOnAThreadWithABoundedStack() {
		assertAll(() -> assertBoundedStackComparison(false), () -> assertBoundedStackComparison(true));
	}

	private static void assertBoundedStackComparison(boolean blankNodes) throws Exception {
		List<SolutionBagCodec.Row> leftRows = new ArrayList<>();
		List<SolutionBagCodec.Row> rightRows = new ArrayList<>();
		for (int index = 0; index < 4096; index++) {
			Value left = blankNodes ? VF.createBNode("left-" + index) : Values.iri("urn:codec:value:" + index);
			Value right = blankNodes ? VF.createBNode("right-" + index) : left;
			leftRows.add(new SolutionBagCodec.Row(List.of(left)));
			rightRows.add(new SolutionBagCodec.Row(List.of(right)));
		}
		var left = SolutionBagCodec.fromRows(List.of("value"), leftRows);
		var right = SolutionBagCodec.fromRows(List.of("value"), rightRows);
		FutureTask<Boolean> comparison = new FutureTask<>(() -> SolutionBagCodec.isomorphic(left, right));
		Thread worker = new Thread(null, comparison, "solution-bag-small-stack", 256 * 1024);
		worker.start();
		try {
			assertTrue(comparison.get());
		} finally {
			worker.join();
		}
	}

	@Test
	void comparesRowMultiplicitiesWithoutSummingPastLongMaxValue() {
		var first = new SolutionBagCodec.Row(List.of(Values.iri("urn:codec:first")));
		var second = new SolutionBagCodec.Row(List.of(Values.iri("urn:codec:second")));
		var left = new SolutionBagCodec.Bag(List.of("value"), List.of(
				new SolutionBagCodec.RowMultiplicity(first, Long.MAX_VALUE),
				new SolutionBagCodec.RowMultiplicity(second, 1L)));
		var right = new SolutionBagCodec.Bag(List.of("value"), List.of(
				new SolutionBagCodec.RowMultiplicity(second, 1L),
				new SolutionBagCodec.RowMultiplicity(first, Long.MAX_VALUE)));

		assertTrue(SolutionBagCodec.isomorphic(left, right));
	}

	private static SolutionBagCodec.Row edge(String subjectId, String objectId) {
		return new SolutionBagCodec.Row(List.of(VF.createBNode(subjectId), Values.iri("urn:codec:edge"),
				VF.createBNode(objectId)));
	}

	@Test
	void encodingIsStableAcrossBindingAndSolutionIterationOrder() {
		BindingSet first = row("z", Values.iri("urn:z"), "a", Values.literal("alpha"));
		BindingSet firstReordered = row("a", Values.literal("alpha"), "z", Values.iri("urn:z"));
		BindingSet second = row("a", Values.literal("beta"));
		SolutionBagCodec.Bag forward = SolutionBagCodec.fromBindingSets(List.of("z", "a"), List.of(first, second));
		SolutionBagCodec.Bag reversed = SolutionBagCodec.fromBindingSets(List.of("a", "z"),
				List.of(second, firstReordered));

		assertEquals(SolutionBagCodec.encode(forward), SolutionBagCodec.encode(reversed));
		assertEquals(forward, SolutionBagCodec.decode(SolutionBagCodec.encode(forward)));
	}

	private static BindingSet row(Object... bindings) {
		MapBindingSet result = new MapBindingSet(bindings.length / 2);
		for (int i = 0; i < bindings.length; i += 2) {
			result.addBinding((String) bindings[i], (Value) bindings[i + 1]);
		}
		return result;
	}
